package za.ac.cput.service; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import za.ac.cput.domain.MaintenanceRecord; import static org.junit.jupiter.api.Assertions.*; @SpringBootTest class MaintenanceRecordServiceImplTest{@Autowired MaintenanceRecordService service; @Test void crud(){MaintenanceRecord x=new za.ac.cput.domain.MaintenanceRecord.Builder().setRecordId("M001").setVehicleId("V1").setDate(java.time.LocalDate.now()).setDescription("Oil").setCost(100).setTechnicianName("Tech").build(); MaintenanceRecord saved=service.create(x); assertNotNull(saved); String id="M001"; assertNotNull(service.read(id)); assertTrue(service.delete(id)); assertNull(service.read(id));}}